public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    if (n == 0) {
        res.add(new java.util.ArrayList<>());
        return res;
    }
    int[] arr = nums.clone();
    java.util.Arrays.sort(arr);
    do {
        java.util.List<Integer> perm = new java.util.ArrayList<>(n);
        for (int num : arr) {
            perm.add(num);
        }
        res.add(perm);
    } while (nextPermutation(arr));
    return res;
}

private boolean nextPermutation(int[] arr) {
    int i = arr.length - 1;
    while (i > 0 && arr[i - 1] >= arr[i]) {
        i--;
    }
    if (i == 0) {
        return false;
    }
    int j = arr.length - 1;
    while (arr[i - 1] >= arr[j]) {
        j--;
    }
    int temp = arr[i - 1];
    arr[i - 1] = arr[j];
    arr[j] = temp;
    int l = i, r = arr.length - 1;
    while (l < r) {
        int t = arr[l];
        arr[l] = arr[r];
        arr[r] = t;
        l++;
        r--;
    }
    return true;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    if (nums.length == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

