    for (int num : nums) {
        List<List<Integer>> newRes = new ArrayList<>();
        for (List<Integer> seq : res) {
            for (int i = 0; i <= seq.size(); i++) {
                List<Integer> newSeq = new ArrayList<>(seq);
                newSeq.add(i, num);
                newRes.add(newSeq);
            }
        }
        res = newRes;
    }
