    }
    Set<String> common = null;
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        int len = s.length();
        Set<String> current = new HashSet<>();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String sub = s.substring(i, j);
                current.add(sub);
                current.add(new StringBuilder(sub).reverse().toString());
            }
        }
        if (common == null) {
            common = current;
        } else {
            common.retainAll(current);
            if (common.isEmpty()) {
                return 0;
            }
        }
    }
    int maxLen = 0;
    for (String str : common) {
        if (str.length() > maxLen) {
            maxLen = str.length();
        }
    }
    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Normalize null elements to empty strings
    List<String> sanitized = new ArrayList<>();
    for (String s : strings) {
        sanitized.add(s == null ? "" : s);
    }
    // Pick the shortest string as base for efficiency
    String base = sanitized.get(0);
    for (String s : sanitized) {
        if (s.length() < base.length()) {
            base = s;
        }
    }
    if (base.isEmpty()) {
        return 0;
    }
    int baseLen = base.length();
    // Iterate lengths from longest to shortest
    for (int len = baseLen; len >= 1; len--) {
        for (int i = 0; i + len <= baseLen; i++) {
            String candidate = base.substring(i, i + len);
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (String t : sanitized) {
                if (!(t.contains(candidate) || t.contains(reversed))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
