    }
    // Consider the first string as the source for candidate substrings
    String first = strings.get(0);
    if (first == null || first.isEmpty()) {
        return 0;
    }

    // Preprocess all strings: if any string is null treat it as empty string
    // Also check if any string is empty; if so, only length 0 can satisfy all
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }

    int firstLen = first.length();
    // Try lengths from longest to shortest
    for (int len = firstLen; len >= 1; len--) {
        // Enumerate all substrings of this length in the first string
        for (int start = 0; start <= firstLen - len; start++) {
            String candidate = first.substring(start, start + len);
            String revCandidate = new StringBuilder(candidate).reverse().toString();

            // Examine both the candidate and its reverse as possible X
            for (String cand : new String[]{candidate, revCandidate}) {
                boolean ok = true;
                // Check that for every string in the list, cand or its reverse occurs
                for (String other : strings) {
                    if (!other.contains(cand) && !other.contains(new StringBuilder(cand).reverse().toString())) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    return len;
                }
            }
        }
    }
    return 0;
}

