        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    // 8 possible directions (horizontal, vertical, diagonal)
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    // Stack for iterative DFS
    int maxSize = rows * cols;
    int[] stackR = new int[maxSize];
    int[] stackC = new int[maxSize];

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                int top = -1;
                // Push starting cell
                top++;
                stackR[top] = r;
                stackC[top] = c;
                visited[r][c] = true;

                while (top >= 0) {
                    int curR = stackR[top];
                    int curC = stackC[top];
                    top--; // pop

                    for (int d = 0; d < 8; d++) {
                        int nr = curR + dr[d];
                        int nc = curC + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            grid[nr][nc] == '@' && !visited[nr][nc]) {
                            top++;
                            stackR[top] = nr;
                            stackC[top] = nc;
                            visited[nr][nc] = true;
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

