            gcd = tempDen;
            tempDen = t;
        }
        int numRed = commonSum / gcd;
        int denRed = denom / gcd;
        if (denRed == 1) {
            result = String.valueOf(numRed);
        } else {
            result = numRed + "/" + denRed;
        }
    }
