            return new int[]{prevIndex, i};
        }
        map.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

public int[] twoSum(int[] nums, int target) {
    // Validate input
    if (nums == null || nums.length < 2) {
        return new int[]{-1, -1};
    }
    // Brute-force search; guaranteed solution according to the problem statement
    for (int i = 0; i < nums.length - 1; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return new int[]{i, j};
            }
        }
    }
    // If no solution found, return a sentinel value
    return new int[]{-1, -1};
}

