public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = n / 20; // 5% of the elements (floor)
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }
    int count = n - 2 * removeCount;
    return count == 0 ? 0.0 : (double) sum / count;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int trim = (int) Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    double sum = 0.0;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    int count = n - 2 * trim;
    if (count <= 0) {
        return 0.0;
    }
    return sum / count;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20; // 5% of n, floored
    java.util.Arrays.sort(arr);
    long sum = 0;
    int start = k;
    int end = n - k; // exclusive
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    int count = end - start;
    if (count == 0) {
        return 0.0;
    }
    return sum / (double) count;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int cut = n / 20; // number of elements to remove from each side
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = cut; i < n - cut; i++) {
        sum += sorted[i];
    }
    return (double) sum / (n - 2 * cut);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removed = n / 20; // 5% of the elements
    if (removed == 0) { // If less than 20 elements, just return the average of all elements
        long total = 0L;
        for (int v : arr) {
            total += v;
        }
        return total / (double) n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long total = 0L;
    for (int v : sorted) {
        total += v;
    }
    long removeSmallSum = 0L;
    for (int i = 0; i < removed; i++) {
        removeSmallSum += sorted[i];
    }
    long removeLargeSum = 0L;
    for (int i = n - removed; i < n; i++) {
        removeLargeSum += sorted[i];
    }
    long remainingSum = total - removeSmallSum - removeLargeSum;
    int remainingCount = n - 2 * removed;
    if (remainingCount <= 0) {
        return 0.0;
    }
    return remainingSum / (double) remainingCount;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    if (k == 0) return false; // division by zero not allowed

    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int r = entry.getKey();
        int cnt = entry.getValue();
        int complement = (k - r) % k;
        if (r == complement) {
            if (cnt % 2 != 0) return false;
        } else {
            int compCnt = freq.getOrDefault(complement, 0);
            if (cnt != compCnt) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (arr.length % 2 != 0) {
        return false; // odd length cannot form pairs
    }
    if (k <= 0) {
        return false; // division by non‑positive k is undefined
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // ensure non‑negative remainder
        freq[rem]++;
    }

    // Remainder 0 must pair with itself
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also pair with itself
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For other remainders, counts must match complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        int opposite = k - r;
        if (r == opposite) { // already handled even k case
            continue;
        }
        if (freq[r] != freq[opposite]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

