    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled for even k
        }
        if (freq[r] != freq[k - r]) {
