}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq.put(rem, freq.getOrDefault(rem, 0) + 1);
    }
    for (int rem : freq.keySet()) {
        int countRem = freq.get(rem);
        if (rem == 0) {
            if (countRem % 2 != 0) {
                return false;
            }
        } else if ((rem * 2) % k == 0) { // k even and rem == k/2
            if (countRem % 2 != 0) {
                return false;
            }
        } else {
            int complement = (k - rem) % k;
            int countComp = freq.getOrDefault(complement, 0);
            if (countRem != countComp) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    dfs(0, -1, adj, hasApple, res);
    return res[0];
}

private boolean dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, int[] res) {
    boolean has = hasApple[node];
    for (int neighbor : adj[node]) {
        if (neighbor == parent) continue;
        boolean childHas = dfs(neighbor, node, adj, hasApple, res);
        if (childHas) {
            res[0] += 2; // go to child and back
            has = true;
        }
    }
    return has;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length == 0) {
        return 0;
    }
    if (edges == null || edges.length == 0) {
        return 0;
    }
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            continue;
        }
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] time = new int[1]; // use array to hold mutable result

    boolean dfs(int node, int parent) {
        boolean subtreeHasApple = hasApple[node];
        for (int neighbor : graph[node]) {
            if (neighbor == parent) {
                continue;
            }
            if (dfs(neighbor, node)) {
                time[0] += 2;
                subtreeHasApple = true;
            }
        }
        return subtreeHasApple;
    }

    dfs(0, -1);
    return time[0];
}

