public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    boolean[] subtreeHasApple = new boolean[n];
    int ans = 0;
    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
    stack.push(new int[]{0, -1, 0}); // node, parent, state(0=pre,1=post)
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int par = cur[1];
        int state = cur[2];
        if (state == 0) {
            stack.push(new int[]{node, par, 1});
            for (int nb : adj[node]) {
                if (nb == par) continue;
                stack.push(new int[]{nb, node, 0});
            }
        } else {
            boolean has = hasApple[node];
            for (int nb : adj[node]) {
                if (nb == par) continue;
                if (subtreeHasApple[nb]) {
                    has = true;
                }
            }
            subtreeHasApple[node] = has;
            if (node != 0 && has) {
                ans += 2;
            }
        }
    }
    return ans;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] parent = new int[n];
    boolean[] visited = new boolean[n];
    int[] order = new int[n];
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int top = 0;
    stack.push(0);
    visited[0] = true;
    parent[0] = -1;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[top++] = node;
        for (int nb : graph[node]) {
            if (!visited[nb]) {
                visited[nb] = true;
                parent[nb] = node;
                stack.push(nb);
            }
        }
    }
    int[] cost = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        int total = 0;
        for (int nb : graph[node]) {
            if (parent[nb] == node) {
                if (cost[nb] > 0 || hasApple[nb]) {
                    total += cost[nb] + 2;
                }
            }
        }
        cost[node] = total;
    }
    return cost[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    char[] arr = s.toCharArray();
    java.util.Arrays.sort(arr);
    StringBuilder sb = new StringBuilder(arr.length);
    int start = 0;
    int end = arr.length - 1;
    while (start <= end) {
        // Ascending pass
        while (start <= end) {
            sb.append(arr[start]);
            start++;
        }
        // Descending pass
        while (start <= end) {
            sb.append(arr[end]);
            end--;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? null : "";
    }

    // Frequency array for Unicode characters up to 65535
    int[] freq = new int[65536];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }

    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);

    while (remaining > 0) {
        // Ascending part: pick strictly increasing characters
        int lastPicked = -1; // sentinel for "no character picked yet"
        for (int c = 0; c < freq.length; c++) {
            if (freq[c] > 0 && (lastPicked == -1 || c > lastPicked)) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
                lastPicked = c;
            }
        }

        if (remaining == 0) {
            break;
        }

        // Descending part: pick strictly decreasing characters
        lastPicked = -1;
        for (int c = freq.length - 1; c >= 0; c--) {
            if (freq[c] > 0 && (lastPicked == -1 || c < lastPicked)) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
                lastPicked = c;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? null : "";
    }
    int[] freq = new int[65536];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }

    StringBuilder res = new StringBuilder();
    boolean ascending = true;

    while (res.length() < s.length()) {
        if (ascending) {
            int last = -1; // sentinel smaller than any char
            for (int i = 0; i < freq.length; i++) {
                if (freq[i] > 0 && i > last) {
                    res.append((char) i);
                    freq[i]--;
                    last = i;
                }
            }
        } else {
            int last = 65536; // sentinel larger than any char
            for (int i = freq.length - 1; i >= 0; i--) {
                if (freq[i] > 0 && i < last) {
                    res.append((char) i);
                    freq[i]--;
                    last = i;
                }
            }
        }
        ascending = !ascending;
    }

    return res.toString();
}

public String sortString(String s) {
    if (s == null) return null;
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (total > 0) {
        for (int i = 0; i < 256; i++) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                total--;
            }
        }
        for (int i = 255; i >= 0; i--) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                total--;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        map.put(ch, map.getOrDefault(ch, 0) + 1);
    }

    java.lang.StringBuilder result = new java.lang.StringBuilder();

    while (!map.isEmpty()) {
        // Step 1: Pick the smallest character
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        result.append(last);
        int cnt = map.get(last) - 1;
        if (cnt == 0) {
            map.remove(last);
        } else {
            map.put(last, cnt);
        }

        // Step 2: Ascending picks
        while (true) {
            java.util.Map.Entry<Character, Integer> nextUp = map.higherEntry(last);
            if (nextUp == null) {
                break;
            }
            last = nextUp.getKey();
            result.append(last);
            cnt = map.get(last) - 1;
            if (cnt == 0) {
                map.remove(last);
            } else {
                map.put(last, cnt);
            }
        }

        if (map.isEmpty()) {
            break;
        }

        // Step 4: Pick the largest character
        java.util.Map.Entry<Character, Integer> lastEntry = map.lastEntry();
        last = lastEntry.getKey();
        result.append(last);
        cnt = map.get(last) - 1;
        if (cnt == 0) {
            map.remove(last);
        } else {
            map.put(last, cnt);
        }

        // Step 5: Descending picks
        while (true) {
            java.util.Map.Entry<Character, Integer> nextDown = map.lowerEntry(last);
            if (nextDown == null) {
                break;
            }
            last = nextDown.getKey();
            result.append(last);
            cnt = map.get(last) - 1;
            if (cnt == 0) {
                map.remove(last);
            } else {
                map.put(last, cnt);
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int v : nums) {
        total += v;
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (hasSubsetOfSizeWithSum(nums, k, target)) {
            return true;
        }
    }
    return false;
}

private boolean hasSubsetOfSizeWithSum(int[] nums, int k, int target) {
    int n = nums.length;
    int leftSize = n / 2;
    int rightSize = n - leftSize;

    java.util.List<java.util.List<Integer>> leftSums = new java.util.ArrayList<>(leftSize + 1);
    java.util.List<java.util.List<Integer>> rightSums = new java.util.ArrayList<>(rightSize + 1);
    for (int i = 0; i <= leftSize; i++) {
        leftSums.add(new java.util.ArrayList<>());
    }
    for (int i = 0; i <= rightSize; i++) {
        rightSums.add(new java.util.ArrayList<>());
    }

    // Generate sums for the left half
    for (int mask = 0; mask < (1 << leftSize); mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                count++;
            }
        }
        leftSums.get(count).add(sum);
    }

    // Generate sums for the right half
    for (int mask = 0; mask < (1 << rightSize); mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[leftSize + i];
                count++;
            }
        }
        rightSums.get(count).add(sum);
    }

    // Convert right sums to sets for faster lookup
    java.util.List<java.util.HashSet<Integer>> rightSets = new java.util.ArrayList<>(rightSize + 1);
    for (int i = 0; i <= rightSize; i++) {
        rightSets.add(new java.util.HashSet<>(rightSums.get(i)));
    }

    // Check combinations of subsets from left and right halves
    for (int leftCount = 0; leftCount <= leftSize; leftCount++) {
        int rightCount = k - leftCount;
        if (rightCount < 0 || rightCount > rightSize) {
            continue;
        }
        java.util.List<Integer> leftList = leftSums.get(leftCount);
        java.util.HashSet<Integer> rightSet = rightSets.get(rightCount);
        for (int leftSum : leftList) {
            if (rightSet.contains(target - leftSum)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int half = n / 2;
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] subsets = new java.util.HashSet[half + 1];
    for (int i = 0; i <= half; i++) {
        subsets[i] = new java.util.HashSet<>();
    }
    subsets[0].add(0);
    for (int num : nums) {
        for (int k = half; k >= 1; k--) {
            for (int prevSum : new java.util.ArrayList<>(subsets[k - 1])) {
                subsets[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= half; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (subsets[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length == 0) return false;
