    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // create array of sets for subset sums of size cnt
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] sumsByCount = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsByCount[i] = new java.util.HashSet<>();
    }
    sumsByCount[0].add(0);
    for (int num : nums) {
        for (int cnt = n - 1; cnt >= 0; cnt--) {
            for (int s : sumsByCount[cnt]) {
                sumsByCount[cnt + 1].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (sumsByCount[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // Early exit: check if any subset size can satisfy the average condition
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue; // target sum must be integer
    }
    // dp[k] holds set of possible sums using exactly k elements
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k in reverse to avoid using the same element multiple times
        int upper = Math.min(maxK, n);
        for (int k = upper; k >= 1; k--) {
            java.util.Set<Integer> prev = dp[k - 1];
            if (prev.isEmpty()) continue;
            java.util.Set<Integer> curr = dp[k];
            for (int sum : prev) {
                curr.add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int half = n / 2;
    int[] left = java.util.Arrays.copyOfRange(nums, 0, half);
    int[] right = java.util.Arrays.copyOfRange(nums, half, n);
    java.util.Map<Integer, java.util.Set<Integer>> mapLeft = new java.util.HashMap<>();
    java.util.Map<Integer, java.util.Set<Integer>> mapRight = new java.util.HashMap<>();
    int leftSize = left.length;
    int rightSize = right.length;
    int leftMaskLimit = 1 << leftSize;
    for (int mask = 0; mask < leftMaskLimit; mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += left[i];
                count++;
            }
        }
        mapLeft.computeIfAbsent(count, k -> new java.util.HashSet<>()).add(sum);
    }
    int rightMaskLimit = 1 << rightSize;
    for (int mask = 0; mask < rightMaskLimit; mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += right[i];
                count++;
            }
        }
        mapRight.computeIfAbsent(count, k -> new java.util.HashSet<>()).add(sum);
    }
    for (int k = 1; k < n; k++) {
        if ((long) totalSum * k % n != 0) continue;
        int target = (int) (((long) totalSum * k) / n);
        for (int leftCount = 0; leftCount <= Math.min(k, leftSize); leftCount++) {
            int rightCount = k - leftCount;
            java.util.Set<Integer> leftSums = mapLeft.get(leftCount);
            java.util.Set<Integer> rightSums = mapRight.get(rightCount);
            if (leftSums == null || rightSums == null) continue;
            for (int s : leftSums) {
                int needed = target - s;
                if (rightSums.contains(needed)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start at step 0 or step 1 (top). Minimum cost is 0.
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i.
    // We only need the last two values.
    int prevPrev = 0; // cost to reach step 0
    int prev = 0;     // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int costFromPrevPrev = prevPrev + cost[i - 2];
        int costFromPrev = prev + cost[i - 1];
        int cur = Math.min(costFromPrevPrev, costFromPrev);
        prevPrev = prev;
        prev = cur;
    }
    return prev;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start from step 1 (the top), so no cost is needed
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

