    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int dp0 = 0; // cost to reach step 0
    int dp1 = 0; // cost to reach step 1
    for (int i = 2; i <= cost.length; i++) {
        int dp2 = Math.min(dp1, dp0) + cost[i - 1];
        dp0 = dp1;
        dp1 = dp2;
    }
    return dp1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0; // nothing to climb
    }
    // dp0: minimal cost to reach step i-2
    // dp1: minimal cost to reach step i-1
    int dpPrevPrev = 0; // cost to reach step 0 (starting point, cost paid later)
    int dpPrev = 0;     // cost to reach step 1 (starting point)

    for (int i = 2; i <= n; i++) {
        int cur = Math.min(dpPrev + cost[i - 1], dpPrevPrev + cost[i - 2]);
        dpPrevPrev = dpPrev;
        dpPrev = cur;
    }
    return dpPrev;
}

