    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= n - k; i++) {
        seen.add(s.substring(i, i + k));
    }
    long total = 1L << k;
    return seen.size() == total;
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0 || k > s.length() || k >= 31) {
        // If k is too large (>30), 1<<k would overflow or require enormous space.
        // In such a case, it's impossible to contain all 2^k codes in a reasonable string length.
        return false;
    }

    int totalCodes = 1 << k;          // Number of possible binary codes of length k
    int mask = totalCodes - 1;        // Mask to keep only k bits

    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;

    int current = 0;
    // Initialize the first (k-1) bits
    for (int i = 0; i < k - 1; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }

    for (int i = k - 1; i < s.length(); i++) {
        // Add the new bit
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[current]) {
            seen[current] = true;
            seenCount++;
            if (seenCount == totalCodes) {
                // All possible codes found early
                return true;
            }
        }
    }
    return seenCount == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    int n = s.length();
    if (n < k) {
        return false;
    }

    // For very large k, the number of possible codes (2^k) is astronomically high
    // and can never be satisfied if n < 2^k.  We use BigInteger to safely compare.
    if (k > 31) { // shifting 1L << 32 or more would overflow a long
        java.math.BigInteger maxCodes = java.math.BigInteger.ONE.shiftLeft(k);
        if (java.math.BigInteger.valueOf(n).compareTo(maxCodes) < 0) {
            return false;
        }
    }

    java.util.Set<Long> seen = new java.util.HashSet<>();
    long curr = 0L;
    long mask = (k == 64) ? -1L : ((1L << k) - 1L);

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // Invalid character encountered; cannot satisfy the condition
            return false;
        }
        int bit = c - '0';
        curr = ((curr << 1) & mask) | bit;
        if (i >= k - 1) {
            seen.add(curr);
            // Early termination if all codes are found
            long required = (k >= 63) ? Long.MAX_VALUE : (1L << k);
            if (seen.size() == required) {
                return true;
            }
        }
    }

    long required = (k >= 63) ? Long.MAX_VALUE : (1L << k);
    return seen.size() == required;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    if (k <= 0) return true; // only the empty string
    int n = s.length();
    if (n < k) return false;

    // Limit k to a reasonable size to avoid huge memory usage
    if (k > 20) return false; // 2^21 would be over 2 million, adjust as needed

    int totalCodes = 1 << k;          // 2^k
    boolean[] seen = new boolean[totalCodes];
    int mask = 0;
    int maskLimit = totalCodes - 1;

    for (int i = 0; i < n; i++) {
        int bit = s.charAt(i) - '0';      // '0' -> 0, '1' -> 1
        mask = ((mask << 1) | bit) & maskLimit; // keep only last k bits
        if (i >= k - 1) {
            seen[mask] = true;
        }
    }

    for (boolean present : seen) {
        if (!present) return false;
    }
    return true;
}

public int isPrefixOfWord(String sentence, String searchWord) {
