public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // Need an opening bracket before this ')'
                insertions++;
            }
        } else {
            // Invalid character: ignore or throw
            // For safety, treat as no-op
        }
    }
    // Add closing brackets for any unmatched '('
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0; // count of unmatched '('
    int insertions = 0; // total insertions required
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            leftNeeded++;
        } else if (c == ')') {
            if (leftNeeded > 0) {
                leftNeeded--; // match with a previous '('
            } else {
                insertions++; // need an extra '(' before this ')'
            }
        } else {
            // If characters other than '(' or ')' appear, throw an exception
            throw new IllegalArgumentException("Input string contains invalid characters: " + c);
        }
    }
    // Any remaining unmatched '(' need corresponding ')' insertions
    insertions += leftNeeded;
    return insertions;
}

