    int balance = 0; // number of unmatched opening brackets '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                insertions++; // need to insert a '(' before this ')'
            }
        } else {
            throw new IllegalArgumentException("Invalid character in input: " + c);
        }
    }
    // Remaining unmatched '(' need ')'
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int unmatchedLeft = 0; // number of '(' that have not been matched yet
    int insertions = 0;    // number of inserted parentheses needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            unmatchedLeft++;
        } else if (c == ')') {
            if (unmatchedLeft > 0) {
                unmatchedLeft--;               // match with an existing '('
            } else {
                insertions++;                    // need to insert a '(' before this ')'
            }
        } else {
            // The problem guarantees only '(' and ')' characters; this block is for robustness.
            // We can ignore or throw an exception depending on desired behavior.
            // For safety, skip the character.
        }
    }
    // Any remaining unmatched '(' require a ')' to be inserted
    insertions += unmatchedLeft;
    return insertions;
}

public int minInsertions(String s) {
