    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    int count = 0;
    int rem = k;
    for (int i = size - 1; i >= 0 && rem > 0; i--) {
        if (fib[i] <= rem) {
            rem -= fib[i];
            count++;
        }
    }
    return count;
}

