public String makeGood(String s) {
    try {
        if (s == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char curr = s.charAt(i);
            int len = sb.length();
            if (len > 0) {
                char last = sb.charAt(len - 1);
                if (Math.abs(last - curr) == 32 && Character.toLowerCase(last) == Character.toLowerCase(curr)) {
                    sb.deleteCharAt(len - 1);
                    continue;
                }
            }
            sb.append(curr);
        }
        return sb.toString();
    } catch (Exception e) {
        // In case of unexpected runtime issue, return an empty string
        return "";
    }
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
