    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Character.toLowerCase(last) == Character.toLowerCase(current)
                && Character.isLowerCase(last) != Character.isLowerCase(current)) {
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(current);
    }
    return sb.toString();
}

/**
 * Makes the given string {@code s} good by repeatedly removing adjacent pairs of characters
 * where one is the lowercase version and the other is the corresponding uppercase version.
 *
 * @param s the input string containing only English letters
 * @return the resulting good string after all possible removals
 */
public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    char[] stack = new char[s.length()];
    int top = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (top > 0 && Math.abs(c - stack[top - 1]) == 32) {
            top--; // remove the opposing pair
        } else {
            stack[top++] = c;
        }
    }
    return new String(stack, 0, top);
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0 && Math.abs(stack.charAt(len - 1) - c) == 32) {
            stack.deleteCharAt(len - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    char[] stack = new char[s.length()];
    int top = 0;
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        if (top > 0) {
            char last = stack[top - 1];
            // Check if last and current are same letter but different case.
            if ((last ^ current) == 32) {
                top--; // Remove the pair.
                continue;
            }
        }
        stack[top++] = current; // Push current onto stack.
    }
    return new String(stack, 0, top);
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    java.util.Set<java.lang.String> used = new java.util.HashSet<>();
    int[] max = {0};
    backtrack(s, 0, used, 0, max);
    return max[0];
}

private void backtrack(String s, int pos, java.util.Set<java.lang.String> used, int count, int[] max) {
    if (pos == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        java.lang.String sub = s.substring(pos, i);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        backtrack(s, i, used, count + 1, max);
        used.remove(sub);
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1); // for n==1 this evaluates to 1
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        boolean ok = true;
        int start = 0;
        for (int pos = 1; pos <= n; pos++) {
            // check if we split at this position
            if (pos == n || ((mask >> (pos - 1)) & 1) == 1) {
                String sub = s.substring(start, pos);
                if (!seen.add(sub)) {
                    ok = false;
                    break;
                }
                start = pos;
            }
        }
        if (ok) {
            max = Math.max(max, seen.size());
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int[] max = new int[1];
    java.util.HashSet<String> seen = new java.util.HashSet<>();
    dfs(0, s, seen, max);
    return max[0];
}

private void dfs(int pos, String s, java.util.HashSet<String> seen, int[] max) {
    if (pos == s.length()) {
        if (seen.size() > max[0]) {
            max[0] = seen.size();
        }
        return;
    }
    // Update max in case the remaining portion cannot form a new unique substring
    if (seen.size() > max[0]) {
        max[0] = seen.size();
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(end, s, seen, max);
            seen.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    java.util.Set<String> used = new java.util.HashSet<>();
    int[] best = new int[1];
    dfs(0, used, best, n, s);
    return best[0];
}

private void dfs(int pos, java.util.Set<String> used, int[] best, int n, String s) {
    if (pos == n) {
        if (used.size() > best[0]) {
            best[0] = used.size();
        }
        return;
    }
    int remaining = n - pos;
    if (used.size() + remaining <= best[0]) {
        return;
    }
    for (int end = pos + 1; end <= n; end++) {
        String sub = s.substring(pos, end);
        if (used.add(sub)) {
            dfs(end, used, best, n, s);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 1; // at least one part (the whole string)
    int totalMasks = 1 << (n - 1); // cut positions between characters
    for (int mask = 0; mask < totalMasks; mask++) {
        HashSet<String> seen = new HashSet<>();
        int start = 0;
        int count = 0;
        boolean ok = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // cut after position i
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    ok = false;
                    break;
                }
                count++;
                start = i + 1;
            }
        }
        if (!ok) {
            continue;
        }
        // Add the last substring
        String last = s.substring(start);
        if (!seen.add(last)) {
            continue; // duplicate found
        }
        count++; // include last part
        if (count > max) {
            max = count;
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in current folder, no change
            continue;
        } else {
            // directory name ending with '/'
            if (!log.isEmpty() && log.charAt(log.length() - 1) == '/') {
                depth++;
            }
        }
    }
    return depth;
}

