    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("String length must be positive.");
    }
    int minPossible = n;          // all 'a's
    int maxPossible = 26 * n;     // all 'z's
    if (k < minPossible || k > maxPossible) {
        throw new IllegalArgumentException("k must be between " + minPossible + " and " + maxPossible + ".");
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int delta = k - n; // how much to add beyond all 'a's
    for (int i = n - 1; i >= 0 && delta > 0; i--) {
        int inc = Math.min(delta, 25); // maximum increment per position
        result[i] = (char) ('a' + inc);
        delta -= inc;
    }
    return new String(result);
}

