public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        // If the array is null or empty, there is no unique element.
        // Returning 0 as a neutral value; alternatively, could throw an exception.
        return 0;
    }
    long result = 0L;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> i) & 1;
        }
        bitCount %= 3;
        if (bitCount != 0) {
            result |= ((long) bitCount << i);
        }
    }
    return (int) result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int[] bitCounts = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >>> i) & 1) == 1) {
                bitCounts[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCounts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        ones &= ~twos;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        int newOnes = (ones ^ num) & ~twos;
        int newTwos = (twos ^ num) & ~newOnes;
        ones = newOnes;
        twos = newTwos;
    }
    return ones;
}

/**
 * Finds the element that appears only once in an array where every other element appears
 * three times.
 *
 * @param nums an integer array where each element appears three times except one
 * @return the element that appears only once; returns 0 if the input is null or empty
 */
public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int common = ones & twos;
        ones &= ~common;
        twos &= ~common;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = (long) num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
        if (lastDigit < 9) {
            long next = (long) num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

