public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (high < 0) {
        // No non-negative stepping numbers in this range
        return result;
    }
    int startLow = Math.max(low, 0);
    // Add single-digit stepping numbers (0-9)
    for (int i = 0; i <= 9; i++) {
        if (i < startLow) {
            continue;
        }
        if (i > high) {
            break;
        }
        result.add(i);
    }
    // BFS queue for multi-digit numbers, start with 1-9 (exclude 0 to avoid leading zeros)
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > high) {
            break;
        }
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

