}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long total = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            total += higher * factor;
        } else if (cur == 1) {
            total += higher * factor + lower + 1;
        } else {
            total += (higher + 1) * factor;
        }
    }
    return (int) total;
}

