public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute perfect squares up to 2 * max(A)
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int k = 0; k * k <= maxSum; k++) {
        squares.add(k * k);
    }
    boolean[] visited = new boolean[n];
    java.util.concurrent.atomic.AtomicInteger count = new java.util.concurrent.atomic.AtomicInteger(0);

    java.util.function.Consumer<Void> dfs = new java.util.function.Consumer<Void>() {
        @Override
        public void accept(Void unused) {
            int depth = 0;
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                visited[i] = true;
                dfsRec(depth + 1, A[i]);
                visited[i] = false;
            }
        }

        private void dfsRec(int depth, int lastVal) {
            if (depth == n) {
                count.incrementAndGet();
                return;
            }
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                if (!squares.contains(lastVal + A[i])) continue;
                visited[i] = true;
                dfsRec(depth + 1, A[i]);
                visited[i] = false;
            }
        }
    };

    dfs.accept(null);
    return count.get();
}

public static int squarePermutations(int[] A) {
    if (A == null) return 0;
    int n = A.length;
    if (n <= 1) return 1;
    java.util.Arrays.sort(A);
    int maxSum = A[n - 1] * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int totalMasks = 1 << n;
    int[][] memo = new int[totalMasks][n];
    for (int i = 0; i < totalMasks; i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    class Solver {
        long dfs(int mask, int lastIdx) {
            if (mask == totalMasks - 1) return 1;
            if (lastIdx >= 0 && memo[mask][lastIdx] != -1) return memo[mask][lastIdx];
            long total = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (lastIdx != -1 && !isSquare[A[i] + A[lastIdx]]) continue;
                    if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                    total += dfs(mask | (1 << i), i);
                }
            }
            if (lastIdx >= 0) memo[mask][lastIdx] = (int) total;
            return total;
        }
    }
    long result = new Solver().dfs(0, -1);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = max * 2;
    boolean[] square = new boolean[maxSum + 1];
    for (int s = 1; s * s <= maxSum; ++s) square[s * s] = true;
    java.util.Arrays.sort(A);
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            can[i][j] = square[A[i] + A[j]];
    int fullMask = (1 << n) - 1;
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();

    class Solver {
        int dfs(int mask, int last) {
            if (mask == fullMask) return 1;
            long key = (((long) mask) << 4) | last;
            Integer val = memo.get(key);
            if (val != null) return val;
            int res = 0;
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) != 0) continue;
                if (!can[last][i]) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                res += dfs(mask | (1 << i), i);
            }
            memo.put(key, res);
            return res;
        }
    }
    Solver solver = new Solver();
    int total = 0;
    for (int i = 0; i < n; ++i) {
        if (i > 0 && A[i] == A[i - 1]) continue;
        total += solver.dfs(1 << i, i);
    }
    return total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    dfs(arr, used, 0, -1, count);
    return count[0];
}

private static void dfs(int[] arr, boolean[] used, int depth, int lastIndex, int[] count) {
    int n = arr.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        // Skip duplicate values to ensure unique permutations by value sequence
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) {
            continue;
        }
        if (depth == 0 || isPerfectSquare((long)arr[lastIndex] + arr[i])) {
            used[i] = true;
            dfs(arr, used, depth + 1, i, count);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(long sum) {
    if (sum < 0) {
        return false;
    }
    long r = (long)Math.round(Math.sqrt(sum));
    return r * r == sum;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    // Precompute square check for sums up to 2 * max(A)
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    // Build adjacency lists
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                adj[i].add(j);
            }
        }
    }

    // DP over subsets
    int maxMask = 1 << n;
    long[][] dp = new long[maxMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0 || dp[mask][last] == 0) {
                continue;
            }
            long cur = dp[mask][last];
            for (int next : adj[last]) {
                if ((mask & (1 << next)) == 0) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    long total = 0;
    int fullMask = maxMask - 1;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }

    // Divide by factorials of duplicate counts
    Map<Integer, Integer> freq = new HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }
    long denom = 1;
    long[] fact = new long[13];
    fact[0] = 1;
    for (int i = 1; i < fact.length; i++) {
        fact[i] = fact[i - 1] * i;
    }
    for (int count : freq.values()) {
        denom *= fact[count];
    }

    long result = total / denom;
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int currHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > currHeight) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

