public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;
    for (int sum = 0; sum < rows + cols - 1; sum++) {
        int iStart = Math.max(0, sum - (cols - 1));
        int iEnd = Math.min(rows - 1, sum);
        if (sum % 2 == 0) {
            for (int i = iEnd; i >= iStart; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = iStart; i <= iEnd; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];
    int r = 0, c = 0; // current position
    int dir = 1; // 1 indicates moving up-right, -1 moving down-left
    for (int i = 0; i < total; i++) {
        result[i] = mat[r][c];
        // decide next position
        if (dir == 1) { // moving up-right
            if (c == cols - 1) { // reach last column
                r++;
                dir = -1;
            } else if (r == 0) { // reach first row
                c++;
                dir = -1;
            } else {
                r--;
                c++;
            }
        } else { // moving down-left
            if (r == rows - 1) { // reach last row
                c++;
                dir = 1;
            } else if (c == 0) { // reach first column
                r++;
                dir = 1;
            } else {
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
