public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = 0;
    for (int k = 0; k < len; k++) {
        result = result * 10 + (digits[k] - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // result would overflow int
        }
    }
    return (int) result;
}

public static int findSmallestInteger(int n) {
    // Convert integer n to a character array of its digits
    char[] digits = Integer.toString(n).toCharArray();

    // Step 1: Find the largest index i such that digits[i] < digits[i + 1]
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, n is the highest permutation of its digits
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the largest index j greater than i such that digits[j] > digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap the characters at indices i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the suffix starting at i + 1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert the resulting digit array back to an integer
    try {
        int result = Integer.parseInt(new String(digits));

        // Ensure the new result is strictly greater than the original n
        if (result <= n) {
            return -1;
        }
        return result;
    } catch (NumberFormatException e) {
        // In case the number is too large for int, treat as impossible
        return -1;
    }
}

