    if (i < 0) {
        return -1; // No larger permutation exists
    }

    // Find the rightmost index 'j' such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert the resulting digit array back to a number, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // Result exceeds int range
        }
    }

    return (int) result;
}

