private static List<String> generateStrobogrammatic(int currLen, int totalLen) {
    List<String> result = new ArrayList<>();
    if (currLen == 0) {
        result.add("");
        return result;
    }
    if (currLen == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    List<String> inner = generateStrobogrammatic(currLen - 2, totalLen);
    String[][] pairs = {{"0", "0"}, {"1", "1"}, {"8", "8"}, {"6", "9"}, {"9", "6"}};

    for (String innerStr : inner) {
        for (String[] pair : pairs) {
            if (currLen == totalLen && pair[0].equals("0")) {
                continue; // skip leading zero for the outermost layer
            }
            result.add(pair[0] + innerStr + pair[1]);
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
