public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, java.util.List<Integer> res) {
    if (current > n) {
        return;
    }
    res.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = current * 10L + d;
        if (next > n) {
            break;
        }
        dfs((int) next, n, res);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(Math.max(0, n));
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while ((current % 10 == 9) || (current + 1 > n)) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, java.util.List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i < 10; i++) {
        long next = (long) current * 10 + i;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current <= n / 10) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current += 1;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int curr = stack.pop();
        if (curr > n) {
            continue;
        }
        result.add(curr);
        for (int d = 9; d >= 0; d--) {
            long next = (long) curr * 10 + d;
            if (next <= n) {
                stack.push((int) next);
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

