        if (count == 1) {
            sum += value;
        }
        i = j;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            min = Math.min(min, dp[i - square] + 1);
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0; // For non‑positive input, no squares are needed
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all 1^2
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        int sqrtRem = (int) Math.sqrt(remainder);
        if (sqrtRem * sqrtRem == remainder) {
            return 2;
        }
    }
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] dp = new int[n + 1];
    final int INF = Integer.MAX_VALUE / 2;
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = INF;
        int s = 1;
        while (s * s <= i) {
            int square = s * s;
            min = Math.min(min, dp[i - square] + 1);
            s++;
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) != ' ') {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        } else {
            while (i < n && s.charAt(i) == ' ') {
                result.append(' ');
                i++;
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? null : "";
    }
    StringBuilder result = new StringBuilder(s.length());
    int i = 0;
    while (i < s.length()) {
        if (s.charAt(i) == ' ') {
            // Preserve spaces as they are
            result.append(' ');
            i++;
        } else {
            // Find end of the current word
            int end = i;
            while (end < s.length() && s.charAt(end) != ' ') {
                end++;
            }
            // Append reversed word
            for (int k = end - 1; k >= i; k--) {
                result.append(s.charAt(k));
            }
            i = end;
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int start = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            // reverse the word before the space
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
            result.append(' ');
            start = i + 1;
        }
    }
    // reverse the last word (if any)
    for (int j = s.length() - 1; j >= start; j--) {
        result.append(s.charAt(j));
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}

